import SwiftUI
struct Contact: Identifiable { let id = UUID(); let name: String; let initial: String; let bank: String }
struct TransferView: View {
    @Environment(\.dismiss) private var dismiss; @State private var amount = ""; @State private var selectedContact: Contact?; @State private var showSuccess = false; @FocusState private var amountFocused: Bool
    private let contacts = [Contact(name: "María López", initial: "M", bank: "BBVA •••• 2341"), Contact(name: "Carlos Ruiz", initial: "C", bank: "BCP •••• 8821"), Contact(name: "Ana Torres", initial: "A", bank: "Interbank •••• 5512"), Contact(name: "Pedro Sánchez", initial: "P", bank: "BBVA •••• 7734"), Contact(name: "Lucía Vargas", initial: "L", bank: "Scotiabank •••• 9901")]
    var body: some View {
        ZStack { BBVA.navy.ignoresSafeArea(edges: .top); BBVA.sand.ignoresSafeArea(edges: .bottom); VStack(spacing: 0) { VStack(alignment: .leading, spacing: 16) { HStack { Button { Haptics.tap(); dismiss() } label: { Image(systemName: "xmark").font(.system(size: 16, weight: .bold)).foregroundColor(.white).frame(width: 38, height: 38).background(Circle().fill(Color.white.opacity(0.14))) }; Spacer(); Text("Transferir").font(BBVAFont.title(20)).foregroundColor(.white); Spacer(); Color.clear.frame(width: 38, height: 38) }.padding(.top, Inset.top + 8) }.padding(.horizontal, 20).padding(.bottom, 20).background(BBVA.navy); ScrollView { VStack(alignment: .leading, spacing: 24) { VStack(alignment: .leading, spacing: 12) { Text("¿Cuánto quieres transferir?").font(BBVAFont.body(14, .medium)).foregroundColor(BBVA.slate); HStack(alignment: .firstTextBaseline, spacing: 4) { Text("S/").font(BBVAFont.body(28, .demi)).foregroundColor(amount.isEmpty ? BBVA.line : BBVA.navy); TextField("0.00", text: $amount).keyboardType(.decimalPad).font(BBVAFont.title(48)).foregroundColor(BBVA.navy).focused($amountFocused).autocorrectionDisabled() }.padding(.horizontal, 20).padding(.vertical, 20).frame(maxWidth: .infinity, alignment: .leading).background(RoundedRectangle(cornerRadius: 20, style: .continuous).fill(Color.white).shadow(color: BBVA.navy.opacity(0.06), radius: 12, y: 4)); ScrollView(.horizontal, showsIndicators: false) { HStack(spacing: 10) { ForEach(["50", "100", "200", "500"], id: \.self) { val in Button { Haptics.tap(); amount = val } label: { Text("S/ \(val)").font(BBVAFont.body(14, .demi)).foregroundColor(BBVA.coreBlue).padding(.horizontal, 16).padding(.vertical, 10).background(Capsule().fill(BBVA.serene)) } } } } }; VStack(alignment: .leading, spacing: 12) { Text("Contactos frecuentes").font(BBVAFont.title(18)).foregroundColor(BBVA.navy); VStack(spacing: 10) { ForEach(contacts) { c in ContactRow(contact: c, isSelected: selectedContact?.id == c.id) { Haptics.tap(); withAnimation(.spring(response: 0.3)) { selectedContact = c } } } } }; Button { guard !amount.isEmpty, let _ = selectedContact else { Haptics.error(); return }; Haptics.success(); withAnimation(.spring(response: 0.5)) { showSuccess = true } } label: { HStack { Image(systemName: "arrow.up.right").font(.system(size: 18, weight: .semibold)); Text("Transferir ahora").font(BBVAFont.body(17, .demi)) }.foregroundColor(.white).frame(maxWidth: .infinity).frame(height: 56).background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill((!amount.isEmpty && selectedContact != nil) ? LinearGradient(colors: [BBVA.coreBlue, BBVA.midBlue], startPoint: .leading, endPoint: .trailing) : LinearGradient(colors: [BBVA.coreBlue.opacity(0.35), BBVA.coreBlue.opacity(0.35)], startPoint: .leading, endPoint: .trailing))).shadow(color: (!amount.isEmpty && selectedContact != nil) ? BBVA.coreBlue.opacity(0.28) : .clear, radius: 14, y: 8) }.padding(.top, 8) }.padding(.horizontal, 20).padding(.vertical, 24).frame(maxWidth: .infinity, alignment: .leading).background(UnevenRoundedRectangle(topLeadingRadius: 32, topTrailingRadius: 32).fill(BBVA.sand).ignoresSafeArea(edges: .bottom)) }.scrollIndicators(.hidden) } }.overlay { if showSuccess { SuccessOverlay(amount: amount, contactName: selectedContact?.name ?? "") { dismiss() }.transition(.scale.combined(with: .opacity)) } }
    }
}
struct ContactRow: View { let contact: Contact; let isSelected: Bool; let onTap: () -> Void; var body: some View { Button(action: onTap) { HStack(spacing: 14) { ZStack { Circle().fill(isSelected ? BBVA.coreBlue : BBVA.serene); Text(contact.initial).font(BBVAFont.title(18)).foregroundColor(isSelected ? .white : BBVA.coreBlue) }.frame(width: 48, height: 48); VStack(alignment: .leading, spacing: 2) { Text(contact.name).font(BBVAFont.body(16, .demi)).foregroundColor(BBVA.navy); Text(contact.bank).font(BBVAFont.body(13)).foregroundColor(BBVA.slate) }; Spacer(); if isSelected { Image(systemName: "checkmark.circle.fill").font(.system(size: 22)).foregroundColor(BBVA.coreBlue).transition(.scale) } else { Image(systemName: "chevron.right").font(.system(size: 14, weight: .semibold)).foregroundColor(BBVA.line) } }.padding(.horizontal, 16).padding(.vertical, 12).background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(isSelected ? BBVA.serene : Color.white)).overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(isSelected ? BBVA.coreBlue : BBVA.line, lineWidth: isSelected ? 1.5 : 1)) } } }
struct SuccessOverlay: View { let amount: String; let contactName: String; let onDismiss: () -> Void; var body: some View { ZStack { Color.black.opacity(0.5).ignoresSafeArea(); VStack(spacing: 20) { ZStack { Circle().fill(BBVA.success.opacity(0.15)).frame(width: 100, height: 100); Circle().stroke(BBVA.success, lineWidth: 3).frame(width: 80, height: 80); Image(systemName: "checkmark").font(.system(size: 36, weight: .bold)).foregroundColor(BBVA.success) }; Text("¡Transferencia exitosa!").font(BBVAFont.title(22)).foregroundColor(BBVA.navy); VStack(spacing: 4) { Text("S/ \(amount)").font(BBVAFont.title(32)).foregroundColor(BBVA.coreBlue); Text("a \(contactName)").font(BBVAFont.body(15)).foregroundColor(BBVA.slate) }; Button("Listo") { onDismiss() }.buttonStyle(PrimaryButtonStyle()).padding(.top, 12) }.padding(32).frame(maxWidth: 320).background(RoundedRectangle(cornerRadius: 28, style: .continuous).fill(Color.white)).shadow(color: BBVA.navy.opacity(0.25), radius: 30, y: 10) } } }
